// Retrieve the JSON array from the process variable "table_of_impact"
var jsonString = execution.getVariable("table_of_impact");

if (jsonString !== null && typeof jsonString === "string") {
    // Parse the JSON string into a JavaScript array
    var jsonArray = JSON.parse(jsonString);

    // Check if the parsed JSON is an array
    if (Array.isArray(jsonArray)) { 
        // Step 1: Group keys by groupName (preparer data removed)
        var groupMap = {}; // groupName => [ key, key, ... ]

        // Iterate through the JSON array using a traditional for loop
        for (var i = 0; i < jsonArray.length; i++) {
            var item = jsonArray[i];
            var groupName = item.groupName;
            var key = item.key;

            // Initialize the group if not already present
            if (!groupMap[groupName]) {
                groupMap[groupName] = [];
            }

            // Check if key already exists in the group before adding
            if (groupMap[groupName].indexOf(key) === -1) {
                groupMap[groupName].push(key);
            }
        }

        // Generate the groupMapString for display/logging purposes
        var groupMapString = "";
        for (var groupName in groupMap) {
            if (groupMap.hasOwnProperty(groupName)) {
                groupMapString += "<strong>" + groupName + ":</strong><br>";
                for (var k = 0; k < groupMap[groupName].length; k++) {
                    groupMapString += "&nbsp;&nbsp;&nbsp;&nbsp;- " + groupMap[groupName][k] + "<br>";
                }
                groupMapString += "<br>";
            }
        }

        // Step 2: Iterate over groupMap and, using the new method with groupName,
        // retrieve each group's email distribution list, collecting only unique emails.
        var uniqueEmails = {};
        for (var groupName in groupMap) {
            if (groupMap.hasOwnProperty(groupName)) {
                // Use the new method to get the email distribution list for this group
                var mailList = insightSafranDispatchListener.getEmailDistributionListForGroup(execution, groupName);
                if (mailList) {
                    // Split the returned string into individual emails and add to the unique set
                    var emails = mailList.split(",");
                    for (var j = 0; j < emails.length; j++) {
                        var email = emails[j].trim();
                        if (email) {
                            uniqueEmails[email] = true;
                        }
                    }
                }
            }
        }

        // Convert the unique email addresses into a comma-delimited string
        var finalEmailList = Object.keys(uniqueEmails).join(", ");

        // Save the results into process variables
        execution.setVariable("groupMapString", groupMapString);
        execution.setVariable("analysisMailList", finalEmailList);

        // Optional: log the results for debugging purposes
        // java.lang.System.out.println("Group Map String:\n" + groupMapString);
        // java.lang.System.out.println("Unique Email List: " + finalEmailList);
    }
}

